// Lifecycle status of a sent_emails row. Possible values:
// - `queued`: pre-call INSERT; the outbound agent has not
// yet replied.
// - `submitted_to_agent`: agent accepted; `queue_id` is set.
// - `agent_failed`: agent rejected; `error_code` and
// `error_message` carry the reason.
// - `gate_denied`: a recipient-scope gate denied the send;
// the agent was never called. The `gates` array carries
// the denial detail. /send-mail returns 403 in this case
// so callers see the denial synchronously; /sent-emails
// additionally records the row for historical lookup,
// which is when this status appears in a listing.
// - `unknown`: terminal indeterminate; the on-box log
// poller couldn't classify the receiver's response.
// - `delivered` / `bounced` / `deferred` / `wait_timeout`:
// terminal delivery outcomes (see DeliveryStatus).
// - `scheduled`: created with a future `scheduled_at` and
// not yet executed; `scheduled_at` carries the pending
// execution time. Reschedulable via PATCH
// /sent-emails/{id} and cancelable via
// /sent-emails/{id}/cancel while in this status.
// - `canceled`: terminal; a scheduled send canceled before
// execution. `canceled_at` carries the cancellation time
// and nothing was dispatched.
// Ref: #/components/schemas/SentEmailStatus
type SentEmailStatus string

const (
	SentEmailStatusQueued           SentEmailStatus = "queued"
	SentEmailStatusSubmittedToAgent SentEmailStatus = "submitted_to_agent"
	SentEmailStatusAgentFailed      SentEmailStatus = "agent_failed"
	SentEmailStatusGateDenied       SentEmailStatus = "gate_denied"
	SentEmailStatusUnknown          SentEmailStatus = "unknown"
	SentEmailStatusDelivered        SentEmailStatus = "delivered"
	SentEmailStatusBounced          SentEmailStatus = "bounced"
	SentEmailStatusDeferred         SentEmailStatus = "deferred"
	SentEmailStatusWaitTimeout      SentEmailStatus = "wait_timeout"
	SentEmailStatusScheduled        SentEmailStatus = "scheduled"
	SentEmailStatusCanceled         SentEmailStatus = "canceled"
)

// AllValues returns all SentEmailStatus values.
func (SentEmailStatus) AllValues() []SentEmailStatus {
	return []SentEmailStatus{
		SentEmailStatusQueued,
		SentEmailStatusSubmittedToAgent,
		SentEmailStatusAgentFailed,
		SentEmailStatusGateDenied,
		SentEmailStatusUnknown,
		SentEmailStatusDelivered,
		SentEmailStatusBounced,
		SentEmailStatusDeferred,
		SentEmailStatusWaitTimeout,
		SentEmailStatusScheduled,
		SentEmailStatusCanceled,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s SentEmailStatus) MarshalText() ([]byte, error) {
	switch s {
	case SentEmailStatusQueued:
		return []byte(s), nil
	case SentEmailStatusSubmittedToAgent:
		return []byte(s), nil
	case SentEmailStatusAgentFailed:
		return []byte(s), nil
	case SentEmailStatusGateDenied:
		return []byte(s), nil
	case SentEmailStatusUnknown:
		return []byte(s), nil
	case SentEmailStatusDelivered:
		return []byte(s), nil
	case SentEmailStatusBounced:
		return []byte(s), nil
	case SentEmailStatusDeferred:
		return []byte(s), nil
	case SentEmailStatusWaitTimeout:
		return []byte(s), nil
	case SentEmailStatusScheduled:
		return []byte(s), nil
	case SentEmailStatusCanceled:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *SentEmailStatus) UnmarshalText(data []byte) error {
	switch SentEmailStatus(data) {
	case SentEmailStatusQueued:
		*s = SentEmailStatusQueued
		return nil
	case SentEmailStatusSubmittedToAgent:
		*s = SentEmailStatusSubmittedToAgent
		return nil
	case SentEmailStatusAgentFailed:
		*s = SentEmailStatusAgentFailed
		return nil
	case SentEmailStatusGateDenied:
		*s = SentEmailStatusGateDenied
		return nil
	case SentEmailStatusUnknown:
		*s = SentEmailStatusUnknown
		return nil
	case SentEmailStatusDelivered:
		*s = SentEmailStatusDelivered
		return nil
	case SentEmailStatusBounced:
		*s = SentEmailStatusBounced
		return nil
	case SentEmailStatusDeferred:
		*s = SentEmailStatusDeferred
		return nil
	case SentEmailStatusWaitTimeout:
		*s = SentEmailStatusWaitTimeout
		return nil
	case SentEmailStatusScheduled:
		*s = SentEmailStatusScheduled
		return nil
	case SentEmailStatusCanceled:
		*s = SentEmailStatusCanceled
		return nil
	default:
		return errors.Errorf("invalid value: %q", data)
	}
}

// List-row projection of a sent-email record. Drops
// `body_text` and `body_html` to keep paginated responses
// small; fetch /sent-emails/{id} for the full record with
// bodies.
// Ref: #/components/schemas/SentEmailSummary
type SentEmailSummary struct {
	ID     uuid.UUID       `json:"id"`
	Status SentEmailStatus `json:"status"`
	// Timestamp of the most recent status transition.
	// Polling clients should treat `status='queued'` AND
	// `status_changed_at` older than 5 minutes as
	// "stuck-queued" (the post-tx UPDATE failed and the
	// actual delivery state is recoverable from on-box logs
	// via `queue_id` when populated, or `request_id`).
	StatusChangedAt time.Time `json:"status_changed_at"`
	CreatedAt       time.Time `json:"created_at"`
	UpdatedAt       time.Time `json:"updated_at"`
	// Effective idempotency key used for this send. If the
	// caller passed the `Idempotency-Key` header, this is
	// that value; otherwise it's a server-derived hash of
	// the canonical request payload.
	ClientIdempotencyKey OptNilString `json:"client_idempotency_key"`
	// Stable hash of the canonical send payload.
	ContentHash string `json:"content_hash"`
	// Raw `From:` header as sent on the wire, including any
	// display name (e.g. `"Acme Support" <agent@acme.test>`).
	FromHeader string `json:"from_header"`
	// Bare email address parsed from `from_header`.
	FromAddress string `json:"from_address"`
	// Raw `To:` header as sent on the wire, including any
	// display name.
	ToHeader string `json:"to_header"`
	// Bare email address parsed from `to_header`.
	ToAddress string `json:"to_address"`
	// Null once the content of a send refused by a gate has been discarded (`content_discarded_at` set).
	Subject NilString `json:"subject"`
	// Total UTF-8 byte length of `body_text` + `body_html`.
	// Surfaced on the list endpoint so callers can see "this
	// row has a 4MB body" without fetching it.
	BodySizeBytes int `json:"body_size_bytes"`
	// Timestamp at which the bodies were discarded by an
	// entitlement-driven retention policy. Null when bodies
	// are still present. The detail endpoint returns
	// null-valued `body_text`/`body_html` for discarded rows.
	ContentDiscardedAt OptNilDateTime `json:"content_discarded_at"`
	// Wire-level Message-ID assigned to the outbound message
	// (RFC 5322). Null on rows that never reached signing
	// (queued, gate_denied, agent_failed before signing).
	MessageID OptNilString `json:"message_id"`
	// Wire-level In-Reply-To header value, when this send
	// was a reply.
	InReplyTo OptNilString `json:"in_reply_to"`
	// Wire-level References header value, when this send
	// was a reply.
	EmailReferences OptNilString `json:"email_references"`
	// Reference to the inbound `emails.id` that this send
	// replied to, when known. Populated when the caller used
	// /emails/{id}/reply or when /send-mail's `in_reply_to`
	// matched a stored inbound message_id in the same org.
	InReplyToEmailID OptNilUUID `json:"in_reply_to_email_id"`
	// Conversation thread this send belongs to. A reply inherits
	// the thread of the inbound it answers; a fresh send starts a
	// new thread. Fetch `/threads/{thread_id}` for the full
	// ordered thread (inbound + outbound interleaved). NULL on
	// gate-denied sends and on sends created before threading was
	// enabled.
	ThreadID OptNilUUID `json:"thread_id"`
	// Message identifier assigned by Primitive's outbound
	// relay once the agent accepts the message. Null on
	// queued, gate_denied, and agent_failed rows.
	QueueID OptNilString `json:"queue_id"`
	// Receiver's 3-digit SMTP code (e.g. 250, 550, 451).
	// Populated on terminal delivery statuses; may be null
	// on a deferred where the agent never got an SMTP-level
	// response (TCP refused, DNS failed, TLS handshake
	// failed). `smtp_response_text` still carries the relay's
	// descriptive text in those cases.
	SMTPResponseCode OptNilInt `json:"smtp_response_code"`
	// Free-form text portion of the receiver's SMTP
	// response. The most useful debugging signal on a
	// `bounced` or `deferred` row.
	SMTPResponseText OptNilString `json:"smtp_response_text"`
	// RFC 3463 enhanced status code (e.g. `5.1.1` for "Bad
	// destination mailbox address"). Distinct from
	// `smtp_response_code`: the basic 3-digit code is coarse
	// (550 = "permanent failure"), the enhanced code is
	// finer-grained.
	SMTPEnhancedStatusCode OptNilString `json:"smtp_enhanced_status_code"`
	// DKIM selector used to sign the outbound message.
	// Public DNS data; useful for diagnosing why a downstream
	// verifier rejected the signature.
	DkimSelector OptNilString `json:"dkim_selector"`
	// DKIM signing domain.
	DkimDomain OptNilString `json:"dkim_domain"`
	// Stable public error code on `agent_failed` rows. The
	// agent's internal codes are remapped to a stable public
	// taxonomy (see `publicAgentError` in the server) so this
	// field is safe to branch on across agent versions.
	ErrorCode OptNilString `json:"error_code"`
	// Free-form error message accompanying `error_code`.
	ErrorMessage OptNilString `json:"error_message"`
	// Gate-denial detail on `gate_denied` rows. Mirrors the
	// synchronous /send-mail 403 contract so a caller's
	// GateDenial handler is the same across live denies and
	// historical lookups. Null on every other status.
	Gates OptNilGateDenialArray `json:"gates"`
	// Server-issued request identifier from the original
	// /send-mail call. Surfaced as the `X-Request-Id`
	// response header on the live send and recorded here
	// for support escalation.
	RequestID OptNilString `json:"request_id"`
	// Requested execution time for a scheduled send. Kept
	// after execution as the historical schedule; null on
	// ordinary immediate sends.
	ScheduledAt OptNilDateTime `json:"scheduled_at"`
	// When a scheduled send was canceled. Null unless the row
	// reached the `canceled` status.
	CanceledAt      OptNilDateTime        `json:"canceled_at"`
	PresenceControl OptNilPresenceControl `json:"presence_control"`
	// Set when Primitive sent this message as part of a repeating send. Resolved from Primitive's own
	// records, never from the message content. Null on every other message and on servers that predate
	// repeating sends.
	Repeat       OptNilSentEmailSummaryRepeat       `json:"repeat"`
	SenderMember OptNilSentEmailSummarySenderMember `json:"sender_member"`
	// Per-recipient SMTP outcomes, including partial failures even when the aggregate send status is
	// delivered. Sender-only; empty when withheld from another recipient or when legacy metadata has no
	// outcomes. Null means stored delivery metadata is unreadable. Optional on older payloads.
	DeliveryRecipients OptNilSentEmailSummaryDeliveryRecipientsItemArray `json:"delivery_recipients"`
	// Plain-text body sent on the wire. Null when the
	// send carried only an HTML body, or when bodies have
	// been discarded post-send (`content_discarded_at`
	// set).
	BodyText OptNilString `json:"body_text"`
	// HTML body sent on the wire. Null when the send
	// carried only a plain-text body, or when bodies
	// have been discarded post-send.
	BodyHTML OptNilString `json:"body_html"`
	// With `include=headers`: stored addressing and threading headers.
	Headers OptNilIncludedMessageHeaders `json:"headers"`
	// Metadata for submitted inline attachments; download availability is reported separately. Metadata
	// may exist when the archive is unavailable, and legacy sends may have no metadata. Offloaded
	// payload files are not included in the inline archive.
	Attachments []SentEmailSummaryAttachmentsItem `json:"attachments"`
	// With `include`: true when a body on this row was cut or left out.
	Truncated OptBool `json:"truncated"`
	// With `include`: the body fields on this row that were cut or left out.
	TruncatedFields []SentEmailSummaryTruncatedFieldsItem `json:"truncated_fields"`
	// How to place this send in a timeline without downloading it, decided when it was sent from the
	// `interaction.json` part it carried (no authentication check: the sending organization wrote it).
	// Same values as on received email except that a send is never `pending`. Decided once by the server
	// from the message's authoritative `interaction.json` part, and for received mail only when a
	// passing DKIM signature covering From and Content-Type authenticates the From that wrote it; the
	// `X-Primitive-Interaction` header is never used, so an unsigned or forged message is always `none`.
	// `status`: a pure status signal (`read`, `working`, `typing`, or an `ack` that is the strict signal
	// shape), to be shown as a property of the message it is about, not as a row. `card`: an interaction
	// that renders as its own timeline item (`ack-request`, `wake.dispatch`, `primitive.contact`,
	// `repeat.tick`, `repeat.stop`, and the reserved `approval` and `schedule.send`). `none`: ordinary
	// mail, including any interaction kind not listed. Treat an unfamiliar value as `none`.
	InteractionHint SentEmailSummaryInteractionHint `json:"interaction_hint"`
	// The `<protocol>/<version>` the hint was decided from when `interaction_hint` is `status` or `card`;
	//  null otherwise.
	InteractionKind NilString `json:"interaction_kind"`
	// A plain-text preview of `body_text` (never `body_html`), computed once when the message is stored:
	// quoted replies (an "On ... wrote:" line, an "Original Message" separator, a From/Sent header block,
	//  `>` lines) and a `-- ` signature are cut off, whitespace is collapsed to single spaces, and the
	// result is at most 200 characters. A message with no text body, or with nothing left once quotes
	// and the signature are cut (a quote-only reply), has no snippet. It is not a summary and may end
	// mid-word; read the full body from the detail endpoint. Null when the send has no text body or its
	// content was discarded.
	Snippet NilString `json:"snippet"`
	// Every recipient of the send, To, Cc and Bcc together, each address counted once: the size of
	// `to_addresses`, `cc` and `bcc` combined without duplicates. On a mail relay send `bcc` lists every
	// hidden recipient. Null when the request uses an address-bound agent connection key whose address
	// is not the sender, because the count would reveal Bcc recipients.
	RecipientCount OptNilInt `json:"recipient_count"`
	// Only on a scheduled send that is not going out yet; status stays scheduled. credential_reuse_hold:
	// its OAuth grant was revoked after refresh token reuse, so it waits until released (POST
	// /sent-emails/{id}/release) or canceled; canceled after 7 days. sending_ip_warmup_cap: your
	// dedicated sending address is at today's warm-up limit or paused, so it goes out on its own within
	// the hour after the limit resets at 00:00 UTC (fails with sending_ip_warmup_cap after 7 such holds);
	//  no release needed. On sent-email reads and conversation messages.
	Hold OptSentEmailSummaryHold `json:"hold"`
}

